import java.io.*;

public class CF1278F_5 {
    static final long MOD = 998244353L;

    public static void main(String[] args) throws IOException {
        int n = readInt();
        int m = readInt();
        int k = readInt();

        long invm = modPow(m, MOD - 2);

        long[] dp = new long[k + 1];
        dp[0] = 1;

        for (int h = 0; h < k; h++)
            for (int d = k - 1; d >= 0; d--) {
                long cur = dp[d];
                if (cur == 0) continue;
                dp[d + 1] = (dp[d + 1] + cur * (n - d)) % MOD;
                dp[d] = cur * d % MOD;
            }

        long p = 1, ans = 0;
        for (int d = 1; d <= k; d++) {
            p = p * invm % MOD;
            ans = (ans + dp[d] * p) % MOD;
        }

        PrintWriter out = new PrintWriter(System.out);
        out.println(ans);
        out.flush();
    }

    static int readInt() throws IOException {
        int c = System.in.read();
        while (c != -1 && c <= ' ') c = System.in.read();

        int sign = 1;
        if (c == '-') {
            sign = -1;
            c = System.in.read();
        } else if (c == '+') {
            c = System.in.read();
        }

        int x = 0;
        while (c != -1 && c > ' ') {
            x = x * 10 + (c - '0');
            c = System.in.read();
        }
        return x * sign;
    }

    static long modPow(long a, long e) {
        long r = 1;
        while (e > 0) {
            if ((e & 1) == 1) r = r * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return r;
    }
}
